"""Offline HTML viewer for trajectory classification algorithm B results."""
from __future__ import annotations

import json
import math
from pathlib import Path
from typing import Any

from plotly.offline.offline import get_plotlyjs


def plotly_up_angle(dx: float, dy: float) -> float:
    """Return a Plotly ``angleref='up'`` marker angle from a Cartesian vector."""
    if dx == 0 and dy == 0:
        raise ValueError("a zero-length segment has no direction")
    return math.degrees(math.atan2(dx, dy))


def _viewer_data(result: dict[str, Any]) -> dict[str, Any]:
    """Copy result data and annotate every non-zero directed segment angle."""
    data = json.loads(json.dumps(result, ensure_ascii=False, sort_keys=True))
    for edge_result in data.get("edges", {}).values():
        for projection in edge_result.get("projections", {}).values():
            for segment in projection.get("directed_segments", []):
                tail, head = segment["tail"], segment["head"]
                dx, dy = head[0] - tail[0], head[1] - tail[1]
                segment["plotly_up_angle"] = (
                    None if dx == 0 and dy == 0 else plotly_up_angle(dx, dy)
                )
    return data


def display_formula_groups(result: dict[str, Any]) -> list[tuple[str, str]]:
    """Return the cross-I/O formula entries shown by the initial viewer mode."""
    return sorted(
        {(name, candidate["formula"])
         for edge in result.get("edges", {}).values()
         for name, projection in edge.get("projections", {}).items()
         for candidate in projection.get("candidates", [])}
    )


def render_html(result: dict[str, Any], output: Path) -> None:
    """Write a deterministic viewer; ``new_stable_inference`` remains optional."""
    data = json.dumps(_viewer_data(result), ensure_ascii=False, sort_keys=True, separators=(",", ":"))
